			function hasChildren(ds, rowIndex, rowCount) {

			    var currRow = ds.getRow(rowIndex);
			    var currLevel = currRow.getValue("CMMNS_CD_LEVELA_NO");
			    
			    // 다음 row 가 존재하면서
			    if (rowIndex + 1 < rowCount) {
			        
			        // 다음 row level 이 더 클 때
			        var nextRow = ds.getRow(rowIndex + 1);
			        var nextLevel = nextRow.getValue("CMMNS_CD_LEVELA_NO");
			        
			        if (currLevel < nextLevel) {
			            return true;
			        }
			    }
			    
			    return false;
			}

			function prevRowIndexSameLevel(ds, rowIndex) {

			    var header = ds.getHeader("CMMNS_CD_LEVELA_NO");
			    //console.log("header", header);
			    
			    if (header == null) {
			        var rowCount = ds.getRowCount();
			        return rowIndex < 1 ? 0 : rowIndex - 1;
			    }
			    
			    var currRow = ds.getRow(rowIndex);
			    var currLevel = currRow.getValue("CMMNS_CD_LEVELA_NO");
			    
			    var findRows = ds.findAllRow("CMMNS_CD_LEVELA_NO <= " + currRow.getValue("CMMNS_CD_LEVELA_NO"));

			    //console.log("findRows2", findRows);
			    
			    var prevIdx = rowIndex;
			    
			    for (var i=0; i < findRows.length; i++) {
			        if (rowIndex > findRows[i].getIndex()) {
			            prevIdx = findRows[i].getIndex();
			        } else {
			            //if (rowIndex == prevIdx) {
			                //return -1;
			            //} else {
			                if (i == 0) {
			                    return -1;
			                } else if (findRows[i - 1].getValue("CMMNS_CD_LEVELA_NO") < currRow.getValue("CMMNS_CD_LEVELA_NO")) {
			                    return -1;
			                } else {
			                    return prevIdx;
			                }
			            //}
			        }
			    }

			    return -1;
			}

			function nextRowIndexSameLevel(ds, rowIndex, small) {

			    var header = ds.getHeader("CMMNS_CD_LEVELA_NO");
			    //console.log("header", header);
			    
			    if (header == null) {
			        var rowCount = ds.getRowCount();
			        return rowIndex + 1 >= rowCount ? rowCount : rowIndex + 1;
			    }
			    
			    var currRow = ds.getRow(rowIndex);
			    var currLevel = currRow.getValue("CMMNS_CD_LEVELA_NO");
			    
			    var findRows = ds.findAllRow("CMMNS_CD_LEVELA_NO <= " + currRow.getValue("CMMNS_CD_LEVELA_NO"));

			    //console.log("findRows1", findRows);
			    
			    if (findRows[findRows.length - 1].getIndex() == rowIndex) {
			        return ds.getRowCount();
			    }

			    var nextIdx = rowIndex;
			        
			    for (var i = findRows.length - 1; i >= 0; i--) {
			        if (rowIndex < findRows[i].getIndex()) {
			            nextIdx = findRows[i].getIndex();
			        } else {
			            if (rowIndex == nextIdx) {
			                return ds.getRowCount();
			            } else {
			                if (small != "small" && findRows[i + 1].getValue("CMMNS_CD_LEVELA_NO") < currRow.getValue("CMMNS_CD_LEVELA_NO")) {
			                    return ds.getRowCount();
			                } else {
			                    return nextIdx;
			                }
			            }
			        }
			    }
			    
			    return ds.getRowCount();
			}


