			function makeCommonCodeToStr() {
			    var dsCommonCode = app.lookup("dsCommonCode");
			    var dsCommonCodeStr = app.lookup("dsCommonCodeStr");
			    
			    dsCommonCodeStr.clear();
			    
			    if (dsCommonCode != null) {
			        var rowCount = dsCommonCode.getRowCount();
			        if (rowCount > 0) {
			            
			            var rowDatas = dsCommonCode.getRowDataRanged();
			            
			            for (var i=0; i < rowDatas.length; i++) {
			                
			                var rowData1 = rowDatas[i]["CMMNS_CD_ID"];
			                var rowData2 = rowDatas[i]["UP_CMMNS_CD_ID"];
			                var rowData3 = rowDatas[i]["CMMNS_CD_NM"];
			                var rowData4 = rowDatas[i]["CMMNS_CD_DSCRP_CN"];
			                var rowData5 = rowDatas[i]["ADDTNG_MNG_VALUE_NM1"];
			                var rowData6 = rowDatas[i]["ADDTNG_MNG_VALUE_NM2"];
			                var rowData7 = rowDatas[i]["ADDTNG_MNG_VALUE_NM3"];
			                var rowData8 = rowDatas[i]["ADDTNG_MNG_VALUE_NM4"];
			                var rowData9 = rowDatas[i]["ADDTNG_MNG_VALUE_NM5"];
			                var rowData10 = rowDatas[i]["CMMNS_CD_LEVELA_NO"];
			                var rowData11 = rowDatas[i]["CMMNS_CD_ID_ORI"];
			                var rowData12 = rowDatas[i]["UNT_SYS_SE_CD"];
			                var rowData13 = rowDatas[i]["CMMNS_CD_CN"];
			                var rowData14 = rowDatas[i]["CMMNS_CD_USE_SCRIN_CN"];
			                
			                var str = rowData1 + "|" + rowData2 + "|" + rowData3 + "|" + rowData4 + "|" 
			                    + rowData5 + "|" + rowData6 + "|" + rowData7 + "|" + rowData8 + "|" 
			                    + rowData9 + "|" + rowData10 + "|" + rowData11 + "|" + rowData12 + "|" 
			                    + rowData13 + "|" + rowData14;
			                
			                var rowData = {str : btoa(unescape(encodeURIComponent(str)))};
			                dsCommonCodeStr.addRowData(rowData);
			            }
			            
			            dsCommonCodeStr.commit();
			        }
			    }
			    
			    
			}

