			function filterValue() {
			    
			    var dsCommonCodeValue = app.lookup("dsCommonCodeValue");
			    
			    var ipb20 = app.lookup("ipb20");
			    var ipb21 = app.lookup("ipb21");
			    
			    //console.log("ipb20", ipb20.value);
			    //console.log("ipb20", ipb20.displayText);
			    //console.log("ipb21", ipb21.value);
			    //console.log("ipb21", ipb21.displayText);
			    
			    dsCommonCodeValue.clearFilter();
			    
			    var filterStr = "";
			    
			    if ((ipb20.displayingText != null && ipb20.displayingText.trim() != "") && (ipb21.displayingText != null && ipb21.displayingText.trim() != "")) {
			        filterStr = "CMMNS_CD_VALUE *= '" + ipb20.displayingText.trim() + "' and CMMNS_CD_VALUE_NM *= '" + ipb21.displayingText.trim() + "'";
			    } else if (ipb20.displayingText != null && ipb20.displayingText.trim() != "") {
			        filterStr = "CMMNS_CD_VALUE *= '" + ipb20.displayingText.trim() + "'";
			    } else if (ipb21.displayingText != null && ipb21.displayingText.trim() != "") {
			        filterStr = "CMMNS_CD_VALUE_NM *= '" + ipb21.displayingText.trim() + "'";
			    }
			    
			    //console.log("filterStr", filterStr);
			    
			    if (filterStr != "") {
			        dsCommonCodeValue.setFilter(filterStr);
			    }
			}

